void mem_check_heap_init(void)
{
    if (!memsysinit)
    {
        CreateAllSemaphores();
        for (int i = 0; i < 6; i++)
        {
            heaps[i].SetHeapID(i);
            heaps[i].FreeHeapMemory();
            heapsize[i] = 0;
            heapmem[i] = 0;
            heapdummyalloc[i] = 0;
        }
        CheckMemorySizeMB();
        Heap::SetHeapMessagers(&KSDebugPrint, &KSHeapError);
        memsysinit = true;

        char *safetyvalve = (char *)malloc(0);
        unsigned int allsize = 0;
        char *allmem = (char *)mem_return_largest_available_block(&allsize);
        if ((allsize > (unsigned int)(0x02000000 - allmem)) && g_debug.simulate32meg)
        {
            heapsize[0] = 0x02000000 - allmem;
            free(allmem);
            heapmem[0] = (char *)malloc(heapsize[0]);
            heapmem[1] = (char *)mem_return_largest_available_block(&heapsize[1]);
        }
        else
        {
            heapsize[0] = allsize;
            heapmem[0] = allmem;
            heapmem[1] = 0;
            heapsize[1] = 0;
        }

        warning("ARCHALLOC: System heap size is %u bytes\n", heapsize[0]);
        heaps[0].SetGranularity(16, 16);
        heaps[0].SetHeapID(0);
        heaps[0].AddHeapMemory(heapmem[0], heapsize[0]);
        heapdummyalloc[0] = heaps[0].Allocate(4, 1, 0, "Dummy allocation", 0);
        heaps[0].CheckConsistency();

        if (heapmem[1])
        {
            heaps[1].SetGranularity(16, 16);
            heaps[1].SetHeapID(1);
            heaps[1].AddHeapMemory(heapmem[1], heapsize[1]);
            heapdummyalloc[1] = heaps[1].Allocate(4, 1, 0, "Dummy allocation", 0);
            heaps[1].CheckConsistency();
        }

        currentheap = &heaps[0];
        heapstack[heapstackptr] = &heaps[0];
        free(safetyvalve);
    }
}
